bool Studio::audioReady(){
    if(!audioEnabled)return true;
    auto* device=deviceManager.getCurrentAudioDevice();
    if(!device||!device->isOpen()||activeOutputs.load()==0){status="Playback cannot start: no active audio output. Open F10 and choose an output device.";repaint();return false;}
    return true;
}
